<script>
(function(){
'use strict';

var c=document.getElementById('canvas'),x=c.getContext('2d'),W,H,D=1,mode='magnet',g=.28,targetCount=80,run=true,objs=[],mouse={x:0,y:0,on:false};
var hm=document.getElementById('h-mode'),hc=document.getElementById('h-count'),hg=document.getElementById('h-g'),he=document.getElementById('h-e'),sg=document.getElementById('sl-g'),sc=document.getElementById('sl-count'),vg=document.getElementById('sv-g'),vc=document.getElementById('sv-count');
function resize(){D=Math.min(2,devicePixelRatio||1);W=c.width=Math.floor(innerWidth*D);H=c.height=Math.floor(innerHeight*D);c.style.width=innerWidth+'px';c.style.height=innerHeight+'px';reset()}function spawn(x0,y0){objs.push({x:x0||Math.random()*W,y:y0||Math.random()*H,vx:(Math.random()-.5)*4*D,vy:(Math.random()-.5)*4*D,r:(4+Math.random()*6)*D})}function reset(){objs=[];for(var i=0;i<targetCount;i++)spawn(W/2,H/3);hud(0)}function step(){if(!run)return;while(objs.length<targetCount)spawn();var e=0;if(mode==='chain'){for(var i=0;i<objs.length;i++){var o=objs[i];o.vy+=g*D;o.x+=o.vx;o.y+=o.vy;if(i){var p=objs[i-1],dx=o.x-p.x,dy=o.y-p.y,d=Math.hypot(dx,dy)||1,rest=18*D,force=(d-rest)*.02;o.vx-=dx/d*force;o.vy-=dy/d*force;p.vx+=dx/d*force;p.vy+=dy/d*force}if(mouse.on&&i===0){o.x=mouse.x;o.y=mouse.y;o.vx=o.vy=0}o.vx*=.99;o.vy*=.99;e+=Math.hypot(o.vx,o.vy)}}else{for(var j=0;j<objs.length;j++){var a=objs[j];a.vy+=g*D;if(mouse.on&&mode==='magnet'){var dx=mouse.x-a.x,dy=mouse.y-a.y,d=Math.hypot(dx,dy)||1;a.vx+=dx/d*.16*D;a.vy+=dy/d*.16*D}a.x+=a.vx;a.y+=a.vy;if(a.x<a.r||a.x>W-a.r){a.vx*=-.86;a.x=Math.max(a.r,Math.min(W-a.r,a.x))}if(a.y<a.r||a.y>H-a.r){a.vy*=-.86;a.y=Math.max(a.r,Math.min(H-a.r,a.y))}a.vx*=.995;a.vy*=.995;e+=Math.hypot(a.vx,a.vy)}}return e}function draw(){var e=step()||0;x.fillStyle='rgba(10,10,15,.22)';x.fillRect(0,0,W,H);x.globalCompositeOperation='lighter';x.strokeStyle='rgba(123,44,191,.18)';x.beginPath();for(var i=1;i<objs.length&&mode==='chain';i++){x.moveTo(objs[i-1].x,objs[i-1].y);x.lineTo(objs[i].x,objs[i].y)}x.stroke();for(var j=0;j<objs.length;j++){var o=objs[j];x.fillStyle=j%2?'rgba(123,44,191,.60)':'rgba(0,245,212,.70)';x.beginPath();x.arc(o.x,o.y,o.r,0,Math.PI*2);x.fill()}x.globalCompositeOperation='source-over';hud(e);requestAnimationFrame(draw)}function hud(e){hm.textContent=mode.toUpperCase();hc.textContent=objs.length;hg.textContent=g.toFixed(2);he.textContent=(e/100).toFixed(2);vg.textContent=g.toFixed(2);vc.textContent=targetCount}c.addEventListener('pointerdown',function(e){mouse={x:e.clientX*D,y:e.clientY*D,on:true};spawn(mouse.x,mouse.y);if(window.SFX)SFX.play('ripple',100)});c.addEventListener('pointermove',function(e){mouse={x:e.clientX*D,y:e.clientY*D,on:e.buttons>0};if(e.buttons&&window.SFX)SFX.play('move',140)});c.addEventListener('pointerup',function(){mouse.on=false});document.querySelectorAll('[data-mode]').forEach(function(b){b.onclick=function(){mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(function(q){q.classList.toggle('active',q===b)});reset();if(window.SFX)SFX.play('toggle')}});sg.oninput=function(){g=+sg.value/100;hud(0)};sc.oninput=function(){targetCount=+sc.value;reset()};document.getElementById('btn-run').onclick=function(e){run=!run;e.currentTarget.classList.toggle('active',run);if(window.SFX)SFX.play('toggle')};document.getElementById('btn-reset').onclick=function(){reset();if(window.SFX)SFX.play('success')};addEventListener('resize',resize);resize();draw();
})();
</script>
